const MIN_GAIN = 0.0001;

export function midiToFrequency(midi) {
  return 440 * 2 ** ((midi - 69) / 12);
}

export function instrumentIdForProgram(instruments, gmProgram) {
  const program = Number(gmProgram);
  if (!Number.isInteger(program) || program < 0 || program > 127) return null;

  return (
    Object.entries(instruments).find(([, preset]) => preset.gm === program)?.[0] ??
    null
  );
}

export function holdAudioParamAtTime(param, time) {
  if (typeof param.cancelAndHoldAtTime === "function") {
    param.cancelAndHoldAtTime(time);
    return;
  }

  const heldValue = Math.max(MIN_GAIN, param.value);
  param.cancelScheduledValues(time);
  param.setValueAtTime(heldValue, time);
}

export class InstrumentEngine {
  constructor(instruments, options = {}) {
    const instrumentIds = Object.keys(instruments);
    if (instrumentIds.length === 0) {
      throw new Error("InstrumentEngine requires at least one instrument");
    }

    const defaultInstrument = options.defaultInstrument ?? instrumentIds[0];
    if (!instruments[defaultInstrument]) {
      throw new Error(`Unknown default instrument: ${defaultInstrument}`);
    }

    this.compressor = null;
    this.context = null;
    this.input = null;
    this.instruments = instruments;
    this.master = null;
    this.masterFilter = null;
    this.maxVoices = options.maxVoices ?? 28;
    this.presetName = defaultInstrument;
    this.sustain = false;
    this.volume = options.volume ?? 0.72;
    this.voiceId = 0;
    this.voices = new Map();
  }

  ensureContext() {
    if (!this.context) {
      const AudioContextClass =
        globalThis.AudioContext || globalThis.webkitAudioContext;
      if (!AudioContextClass) return null;

      this.context = new AudioContextClass({ latencyHint: "interactive" });
      this.input = this.context.createGain();
      this.input.gain.value = 0.78;

      this.masterFilter = this.context.createBiquadFilter();
      this.masterFilter.type = "lowpass";
      this.masterFilter.frequency.value =
        this.instruments[this.presetName].filter;
      this.masterFilter.Q.value = 0.32;

      this.compressor = this.context.createDynamicsCompressor();
      this.compressor.threshold.value = -18;
      this.compressor.knee.value = 18;
      this.compressor.ratio.value = 3;
      this.compressor.attack.value = 0.006;
      this.compressor.release.value = 0.18;

      this.master = this.context.createGain();
      this.master.gain.value = this.volume;

      this.input.connect(this.masterFilter);
      this.masterFilter.connect(this.compressor);
      this.compressor.connect(this.master);
      this.master.connect(this.context.destination);
    }

    if (this.context.state === "suspended") {
      void this.context.resume();
    }

    return this.context;
  }

  noteOn(midi, velocity = 0.78) {
    const context = this.ensureContext();
    if (!context) return null;

    while (this.voices.size >= this.maxVoices) {
      const oldestVoice = this.voices.keys().next().value;
      this.releaseVoice(oldestVoice, 0.06);
    }

    const preset = this.instruments[this.presetName];
    const now = context.currentTime;
    const frequency = midiToFrequency(midi);
    const voiceGain = context.createGain();
    const filter = context.createBiquadFilter();
    const panner = context.createStereoPanner?.();
    const peak = Math.max(0.035, Math.min(0.13, velocity * 0.115));
    const pitchBrightness = Math.min(
      1.25,
      Math.max(0.72, 440 / Math.max(220, frequency)),
    );
    const hasSustain =
      Number.isFinite(preset.sustain) && preset.sustain > 0;

    voiceGain.gain.setValueAtTime(MIN_GAIN, now);
    voiceGain.gain.exponentialRampToValueAtTime(peak, now + preset.attack);
    if (hasSustain) {
      voiceGain.gain.exponentialRampToValueAtTime(
        Math.max(MIN_GAIN, peak * preset.sustain),
        now + preset.attack + preset.decay,
      );
    } else {
      voiceGain.gain.exponentialRampToValueAtTime(peak * 0.34, now + 0.55);
      voiceGain.gain.exponentialRampToValueAtTime(
        MIN_GAIN * 1.2,
        now + preset.decay * pitchBrightness,
      );
    }

    filter.type = "lowpass";
    filter.frequency.value = Math.min(preset.filter, 2200 + frequency * 6);
    filter.Q.value = 0.38;

    let modulationGain = null;
    let tremolo = null;
    if (preset.tremolo) {
      const [rate, rawDepth] = preset.tremolo;
      const depth = Math.max(0, Math.min(1, rawDepth));
      modulationGain = context.createGain();
      modulationGain.gain.value = 1 - depth / 2;

      const oscillator = context.createOscillator();
      const amount = context.createGain();
      oscillator.frequency.value = rate;
      amount.gain.value = depth / 2;
      oscillator.connect(amount);
      amount.connect(modulationGain.gain);
      oscillator.start(now);
      tremolo = { amount, oscillator };

      filter.connect(modulationGain);
      modulationGain.connect(voiceGain);
    } else {
      filter.connect(voiceGain);
    }

    if (panner) {
      panner.pan.value = Math.max(-0.38, Math.min(0.38, (midi - 64) / 90));
      voiceGain.connect(panner);
      panner.connect(this.input);
    } else {
      voiceGain.connect(this.input);
    }

    const oscillators = preset.partials.map(
      ([multiple, gainAmount, detune, waveform = preset.wave ?? "sine"]) => {
        const oscillator = context.createOscillator();
        const partialGain = context.createGain();
        oscillator.type = waveform;
        oscillator.frequency.value = frequency * multiple;
        oscillator.detune.value = detune;
        partialGain.gain.value = gainAmount;
        oscillator.connect(partialGain);
        partialGain.connect(filter);
        oscillator.start(now);
        return { oscillator, partialGain };
      },
    );

    let vibrato = null;
    if (preset.vibrato) {
      const [rate, cents] = preset.vibrato;
      const oscillator = context.createOscillator();
      const amount = context.createGain();
      oscillator.frequency.value = rate;
      amount.gain.value = cents;
      oscillator.connect(amount);
      oscillators.forEach(({ oscillator: partial }) => {
        amount.connect(partial.detune);
      });
      oscillator.start(now);
      vibrato = { amount, oscillator };
    }

    const id = ++this.voiceId;
    const cleanupTimer = hasSustain
      ? null
      : globalThis.setTimeout(
          () => this.disposeVoice(id),
          (preset.decay * pitchBrightness + 0.4) * 1000,
        );

    this.voices.set(id, {
      cleanupTimer,
      filter,
      midi,
      modulationGain,
      oscillators,
      panner,
      release: preset.release,
      released: false,
      sustained: false,
      tremolo,
      vibrato,
      voiceGain,
    });

    return id;
  }

  noteOff(id) {
    const voice = this.voices.get(id);
    if (!voice || voice.released) return;

    if (this.sustain) {
      voice.sustained = true;
      return;
    }

    this.releaseVoice(id);
  }

  releaseVoice(id, releaseOverride) {
    const voice = this.voices.get(id);
    if (!voice || voice.released || !this.context) return;

    voice.released = true;
    voice.sustained = false;
    globalThis.clearTimeout(voice.cleanupTimer);

    const now = this.context.currentTime;
    const release = releaseOverride ?? voice.release;
    holdAudioParamAtTime(voice.voiceGain.gain, now);
    voice.voiceGain.gain.setTargetAtTime(
      MIN_GAIN,
      now,
      Math.max(0.012, release / 5),
    );
    voice.oscillators.forEach(({ oscillator }) =>
      oscillator.stop(now + release + 0.08),
    );
    voice.cleanupTimer = globalThis.setTimeout(
      () => this.disposeVoice(id),
      (release + 0.16) * 1000,
    );
  }

  disposeVoice(id) {
    const voice = this.voices.get(id);
    if (!voice) return;

    globalThis.clearTimeout(voice.cleanupTimer);
    voice.oscillators.forEach(({ oscillator, partialGain }) => {
      try {
        oscillator.stop();
      } catch {
        // The oscillator may already have reached its scheduled stop time.
      }
      oscillator.disconnect();
      partialGain.disconnect();
    });

    [voice.tremolo, voice.vibrato].forEach((modulator) => {
      if (!modulator) return;
      try {
        modulator.oscillator.stop();
      } catch {
        // The modulator may already be stopped.
      }
      modulator.oscillator.disconnect();
      modulator.amount.disconnect();
    });

    voice.filter.disconnect();
    voice.modulationGain?.disconnect();
    voice.voiceGain.disconnect();
    voice.panner?.disconnect();
    this.voices.delete(id);
  }

  setSustain(enabled) {
    this.sustain = Boolean(enabled);
    if (this.sustain) return;

    [...this.voices.entries()]
      .filter(([, voice]) => voice.sustained)
      .forEach(([id]) => this.releaseVoice(id));
  }

  setInstrument(name) {
    if (!this.instruments[name]) return false;
    this.presetName = name;
    if (this.masterFilter && this.context) {
      this.masterFilter.frequency.setTargetAtTime(
        this.instruments[name].filter,
        this.context.currentTime,
        0.03,
      );
    }
    return true;
  }

  setPreset(name) {
    return this.setInstrument(name);
  }

  setProgram(gmProgram) {
    const id = instrumentIdForProgram(this.instruments, gmProgram);
    return id ? this.setInstrument(id) : false;
  }

  setVolume(volume) {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.master && this.context) {
      this.master.gain.setTargetAtTime(
        this.volume,
        this.context.currentTime,
        0.025,
      );
    }
  }

  stopAll() {
    [...this.voices.keys()].forEach((id) => this.releaseVoice(id, 0.04));
  }
}

export class LightweightMidiEngine extends InstrumentEngine {
  constructor(options = {}) {
    super(MIDI_INSTRUMENTS, {
      defaultInstrument: "grand",
      ...options,
    });
  }
}
